module cbench_security_rijndael_decrypt
const input_bytes=48
fn gm(aa u8,bb u8) u8 {mut a:=aa;mut b:=bb;mut r:=u8(0);for b!=0{if b&1!=0{r^=a};a=u8((u16(a)<<1)^(if a&128!=0{u16(0x1b)}else{u16(0)}));b>>=1};return r}
fn gp(aa u8,nn u32) u8 {mut a:=aa;mut n:=nn;mut r:=u8(1);for n!=0{if n&1!=0{r=gm(r,a)};a=gm(a,a);n>>=1};return r}
fn decrypt_block(key [32]u8,input [16]u8) [16]u8 {mut s:=[256]u8{};mut inv:=[256]u8{};for x in 0..256{q:=if x==0{u8(0)}else{gp(u8(x),254)};s[x]=q^u8((u16(q)<<1)|(u16(q)>>7))^u8((u16(q)<<2)|(u16(q)>>6))^u8((u16(q)<<3)|(u16(q)>>5))^u8((u16(q)<<4)|(u16(q)>>4))^0x63};for x in 0..256{inv[s[x]]=u8(x)};rc:=[7]u8{1,2,4,8,16,32,64};mut rk:=[240]u8{};for i in 0..32{rk[i]=key[i]};mut w:=32;for w<240{wi:=w/4;mut t:=[4]u8{rk[w-4],rk[w-3],rk[w-2],rk[w-1]};if wi%8==0{a:=t[0];t[0]=s[t[1]]^rc[wi/8-1];t[1]=s[t[2]];t[2]=s[t[3]];t[3]=s[a]}else if wi%8==4{for j in 0..4{t[j]=s[t[j]]}};for j in 0..4{rk[w]=rk[w-32]^t[j];w++}};mut st:=input;for i in 0..16{st[i]^=rk[224+i]};for round:=13;round>0;round--{p:=st;for c in 0..4{for r in 0..4{st[r+4*c]=inv[p[r+4*((c+4-r)%4)]]}};for i in 0..16{st[i]^=rk[round*16+i]};for c in 0..4{o:=4*c;a,b,d,e:=st[o],st[o+1],st[o+2],st[o+3];st[o]=gm(a,14)^gm(b,11)^gm(d,13)^gm(e,9);st[o+1]=gm(a,9)^gm(b,14)^gm(d,11)^gm(e,13);st[o+2]=gm(a,13)^gm(b,9)^gm(d,14)^gm(e,11);st[o+3]=gm(a,11)^gm(b,13)^gm(d,9)^gm(e,14)}};p:=st;for c in 0..4{for r in 0..4{st[r+4*c]=inv[p[r+4*((c+4-r)%4)]]}};for i in 0..16{st[i]^=rk[i]};return st}
@[export:'cbench_security_rijndael_decrypt']
pub fn cbench_security_rijndael_decrypt(values &i64,length usize,mut output &u8,capacity usize) i64 {unsafe{if values==nil||length!=input_bytes{return -1};for i in 0..input_bytes{if values[i]<0||values[i]>255{return -1}};if output==nil||capacity<16{return -2};mut key:=[32]u8{};mut block:=[16]u8{};for i in 0..32{key[i]=u8(values[i])};for i in 0..16{block[i]=u8(values[32+i])};plain:=decrypt_block(key,block);for i in 0..16{output[i]=plain[i]};return 16}}
